const navbar=document.querySelector('#navbar');const menu=document.querySelector('#menuToggle');const nav=document.querySelector('#navLinks');
addEventListener('scroll',()=>navbar.classList.toggle('scrolled',scrollY>16),{passive:true});
menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',open);document.body.classList.toggle('menu-open',open)});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');document.body.classList.remove('menu-open')}));
const reveal=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');reveal.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(e=>reveal.observe(e));
const numberObserver=new IntersectionObserver(es=>es.forEach(e=>{if(!e.isIntersecting)return;const el=e.target;const n=+el.dataset.count;const start=performance.now();const duration=1200;function tick(now){const p=Math.min(1,(now-start)/duration);const value=Math.round(n*(1-Math.pow(1-p,3)));el.textContent=(el.dataset.prefix||'')+value.toLocaleString('pt-PT')+(el.dataset.suffix||'');if(p<1)requestAnimationFrame(tick)}requestAnimationFrame(tick);numberObserver.unobserve(el)}),{threshold:.5});document.querySelectorAll('[data-count]').forEach(e=>numberObserver.observe(e));
document.querySelectorAll('.tab').forEach(tab=>tab.addEventListener('click',()=>{document.querySelectorAll('.tab').forEach(t=>t.classList.remove('active'));tab.classList.add('active');const f=tab.dataset.filter;document.querySelectorAll('.course').forEach(c=>c.hidden=f!=='todos'&&c.dataset.category!==f)}));
document.querySelectorAll('.faq-q').forEach(q=>q.addEventListener('click',()=>{const item=q.closest('.faq-item');const was=item.classList.contains('open');document.querySelectorAll('.faq-item').forEach(i=>{i.classList.remove('open');i.querySelector('.faq-q').setAttribute('aria-expanded','false');i.querySelector('.faq-a').style.maxHeight=null});if(!was){item.classList.add('open');q.setAttribute('aria-expanded','true');const a=item.querySelector('.faq-a');a.style.maxHeight=a.scrollHeight+'px'}}));
const first=document.querySelector('.faq-item.open .faq-a');if(first)first.style.maxHeight=first.scrollHeight+'px';
